Q: Correct way to try/except using Python requests module? A: <p>I suggested an answer here in 2022. It has at the time of writing 9 upvotes, so I should probably not edit it.
But there is a hugely powerful way of handling requests and resultant <code>requests.Response</code>s which I've found (absolutely sure I'm not the first).</p>
<p>It involves the use of <a href="https://docs.pydantic.dev/latest/concepts/validators/" rel="nofollow noreferrer">Pydantic</a> validation. Unfamiliar classes in what follows are all Pydantic classes.</p>
<pre><code>from pydantic import ValidationError, BaseModel, AnyHttpUrl, validate_call
from typing import Type, Optional, Dict

from mrodent_lib.constants_lib import PROJECT_NAME, TIMEOUT_STRING, GET_STRING, POST_STRING, JSON_STRING,\
    PUT_STRING, PATCH_STRING, DELETE_STRING, HEAD_STRING, OPTIONS_STRING, DATA_STRING, HEADERS_STRING

logger = logging.getLogger(PROJECT_NAME)

def do_request(method, url, base_model_class=None, **kwargs):
    try:
        return inner_do_request(method, url, base_model_class, **kwargs)
    except Exception as e:
        if isinstance(e, ValidationError):
            msg = f&quot;&quot;&quot;args were 
method: {method} type {type(method)}
url: {url} type {type(url)}
base_model_class: {base_model_class} type {type(base_model_class)}
\n{e}&quot;&quot;&quot;
        else:
            # there is no point saying what the types are in this case, as the params passed their validation
            msg = f'args were method: {method}, url: {url}\n{e}'
        logger.error(msg, stack_info=True) # show the stack leading UP TO the call to do_request(..)
        return False, e

@validate_call
def inner_do_request(method: str, url: AnyHttpUrl, base_model_class: Optional[Type[BaseModel]], **kwargs):
    VALID_HTTP_METHODS = {GET_STRING, POST_STRING, PUT_STRING, PATCH_STRING, DELETE_STRING, HEAD_STRING, OPTIONS_STRING}
    DEFAULT_TIMEOUT = 60 # 60 seconds
    if method.lower() not in VALID_HTTP_METHODS:
        raise ValueError(f'illegal request method &quot;{method}&quot;, must be one of {VALID_HTTP_METHODS}')
    kwargs.setdefault(TIMEOUT_STRING, DEFAULT_TIMEOUT)       
    response = requests.request(method, str(url), **kwargs)
    try:
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        # give details of the supplied &quot;json&quot;, &quot;headers&quot;, &quot;data&quot; kwargs (if applicable)
        kwarg_info_str = ''
        for kwarg_arg in [HEADERS_STRING, DATA_STRING, JSON_STRING]:
            if kwarg_arg in kwargs:
                # NB &quot;data&quot; is a string; the others are dicts
                if kwarg_arg == DATA_STRING:
                    # NB
                    kwarg_dict = json.loads(kwargs[DATA_STRING])
                else:
                    kwarg_dict = kwargs[kwarg_arg]
                kwarg_info_str += f'kwarg {kwarg_arg}:\n{json.dumps(kwarg_dict, indent=2)}\n'
                &quot;&quot;&quot;
2026-05-22 NB if the logger's formatters have been configured to truncate (e.g. 1000 characters at the console or
10000 to the file log), then very often this &quot;kwargs info&quot; string will get truncated at the console ... so consult file log         
                &quot;&quot;&quot;
        if kwarg_info_str != '':
            logger.error(kwarg_info_str)
        try:
            logger.error(f'response.json():\n{json.dumps(response.json(), indent=2)}')
        except json.JSONDecodeError:
            logger.error(f'got (non-JSON) response.text:\n|{response.text}|')
        # raise for both HTTPError and for JSONDecodeError    
        raise e
    if base_model_class != None:
        try:
            base_model_class.model_validate(response.json())
        except json.JSONDecodeError:
            &quot;&quot;&quot;
2026-05-22 NB the fact that a base_model_class was supplied as a 3rd parameter must mean that the user
is expecting a Response which can call json() without raising JSONDecodeError ... so such an exception here
represents an error condition            
            &quot;&quot;&quot;
            logger.error(f'expected JSON but got (non-JSON) response.text:\n|{response.text}|')
            raise e
    return True, response
</code></pre>
<p>What you then do is this:</p>
<pre><code>success, deliverable = do_request('get', 'http://localhost:9500') # example
</code></pre>
<p>... <code>success</code> is a <code>bool</code>, <code>deliverable</code> is either a <code>requests.Response</code> (if successful) or an <code>Exception</code> (if not).</p>
<p>So what's the 3rd parameter passed to <code>do_request(..)</code>? If provided, it's a <code>pydantic.BaseModel</code> subclass. Here's how you might use one if, as I do, you have an Elasticsearch server installed at localhost:9500 on your machine:</p>
<pre><code>...
from packaging import version
....

class VersionDict(BaseModel):
    number: str # which means &quot;the examined dict must have a key called &quot;number&quot; and it must be a string&quot;
    @field_validator('number')
    def validate_version(cls, v: str) -&gt; str:
        try:
            es_server_version_found = version.parse(v)  # Raises InvalidVersion if bad
        except Exception as e:
            raise ValueError(f'Invalid version string: {v}') from e
        MIN_ES_VERSION = version.Version('8.0.0')
        if es_server_version_found &lt; MIN_ES_VERSION:
            raise ValueError(fr'Version from response from request for Elasticsearch too low: {es_server_version_found}, min. is {MIN_ES_VERSION}')
        return v
class ServerResponseJson(BaseModel):
    tagline: str
    # standard technique: use a previously defined BaseModel class to define requirements of a nested dict value (see VersionDict definition above):
    version: VersionDict 

# do the command
url = 'http://localhost:9500'
success, deliverable = do_request('get', url, ServerResponseJson)

if not success:

    # ... after-error handling
    return # ... typically

response = deliverable
# ... more operations with the json dict from response.json() ...
</code></pre>
<p>Things might become clearer if I show what <code>Response.json()</code> gives to that URL on my machine:</p>
<pre><code>{
    &quot;name&quot; : &quot;M17A&quot;,
    &quot;cluster_name&quot; : &quot;elasticsearch&quot;,
    &quot;cluster_uuid&quot; : &quot;g7V6cdWnT0Gwto1Brw8h_w&quot;,
    &quot;version&quot; : {
        &quot;number&quot; : &quot;8.13.1&quot;,
        &quot;build_flavor&quot; : &quot;default&quot;,
        &quot;build_type&quot; : &quot;zip&quot;,
        &quot;build_hash&quot; : &quot;9287f29bba5e270bd51d557b8daccb7d118ba247&quot;,
        &quot;build_date&quot; : &quot;2024-03-29T10:05:29.787251984Z&quot;,
        &quot;build_snapshot&quot; : false,
        &quot;lucene_version&quot; : &quot;9.10.0&quot;,
        &quot;minimum_wire_compatibility_version&quot; : &quot;7.17.0&quot;,
        &quot;minimum_index_compatibility_version&quot; : &quot;7.0.0&quot;
    },
    &quot;tagline&quot; : &quot;You Know, for Search&quot;
}    
</code></pre>
<p>... so the class <code>ServerResponseJson</code> is submitted as the 3rd parameter... when <code>model_validate</code> is called by that class, given the returned json dict as the param, it <em>checks</em> that all the stipulations you have set are matched, and if any of these checks fail a <code>ValidationError</code> is raised.</p>
<p>In this case I have stipulated, in the definition of class <code>ServerResponseJson</code>, that two root-level keys must be present: &quot;tagline&quot;, which must be a string, and &quot;version&quot; which must be a <code>VersionDict</code>, which is another (nested) <code>BaseModel</code> class defined by me.</p>
<p>The class definition of <code>VersionDict</code> says: &quot;in that subdict, &quot;version&quot;, there must be a key &quot;number&quot;&quot; ... and the <code>@field_validator</code> rule also requires that that value (which must be a string) must be able to be parsed as a <code>packaging.version.Version</code> object. As configured, if any of these tests fail, a <code>ValidationError</code> is raised, and <code>do_request</code> returns (<code>False</code>, <code>ValidationError</code>).</p>
<p>Also, if it can be parsed it is then compared to a minimum acceptable version of Elasticsearch, and the return would be (<code>False</code>, <code>ValidationError</code>) if the version is too low. NB it can be seen that raising <code>ValueError</code> results in <code>model_validate</code> raising a <code>pydantic.ValidationError</code>.</p>
<p>If the validation process passes OK, however, the return will be (<code>True</code>, the  <code>Response</code>).</p>
<p>Any problems with the request itself, such as bad status code or <code>Timeout</code> or <code>ConnectionError</code>, will also be handled and each will return a (<code>False</code>, <code>Exception</code>). Everything gets logged if you have a logger set up.</p>
<p>You can make the architecture of the main <code>BaseModel</code> class as complex or as simple as you want. Typically each <code>requests.request(..)</code> call is going to need its own architecture.</p>
<p>PS the &quot;inner_do_request&quot; arrangement is so that you can validate that the method (&quot;get&quot;, &quot;put&quot;, etc.) is legal, and the URL is a well-formed URL.</p>
<p>PPS the error messages which <code>ValidationError</code>s produce are dense and seem at first sight a bit cryptic. But they contain the vital info you need to track down the cause of the error. Hence the need to log them systematically.</p>
<p>PPPS The output from <code>response.text</code> or <code>response.json()</code> can be huge, sometimes megabytes (as can the submitted <code>json</code> or <code>data</code> kwargs)! The way I deal with this is the logger's formatter's <code>format()</code> method which truncates if a message is too long. In fact I have a &quot;max string length&quot; which is differs between the <code>StreamHandler</code>'s formatter and the <code>FileHandler</code>'s formatter. Beyond the scope of this question.</p>

Q: Font Not Loading in FabricJS Canvas with WebFontLoader (Dynamic Import) A: <h3>Browsers »lazy« font loading</h3>
<p>All modern browsers are highly optimized to load fonts only if really required. This is incredibly useful in regards of complex font loading CSS such as the ones provided by google fonts: These usually include multiple rules for many unicode-ranges. Fortunately, the browser won't load all files for languages that are not needed for the current document.</p>
<p>Simplified the browser behaves something like this:</p>
<ul>
<li>Parse the CSS - any <code>@font-face</code> rules for font loading? OK but I won't load all of them - let's first check the</li>
<li>HTML/DOM – any elements with the specified font-families and styles applied? If not – I don't load anything</li>
<li>dynamic content created via JS? Ah! there's a request for the font - let's load it for the next refresh</li>
</ul>
<p>So the point is: dynamically created elements won't force the browser to wait for the font to be loaded.</p>
<p>You may wonder: »But I haven't I applied the font to a text object?«<br />
From a browser perspective – you haven't as the fabric.js text-object doesn't qualify as a DOM element.<br />
While <code>setFontLoaded(true)</code> sets the variable to true it obviously doesn't apply the font to a DOM element.</p>
<p>Here are some working (simplified) examples:</p>
<h4>1. Render after font load</h4>
<p>You current code doesn't work as the rendering doesn't wait for the font load promise to be fulfilled. By running the rendering in the font loader active callback we ensure the font is fully available.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="false" data-babel="true" data-babel-preset-react="true" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>console.clear();
const { useState, useEffect } = React;


function App() {

  useEffect(() =&gt; {

    const fontFamily = 'Rasa';

    // Initialize Fabric canvas
    const canvas = new fabric.Canvas("canvas", {
      width: 800,
      height: 200,
      backgroundColor: "#f0f0f0"
    });

    // Add text to canvas
    const text = new fabric.Text("Hamburgefons", {
      left: 50,
      top: 80,
      fontSize: 72,
      fontFamily: fontFamily,
      fill: "#000"
    });


  WebFont.load({
    google: {
      families: [fontFamily]
    },
    active: ()=&gt;{
      //canvas.fontFamily = fontFamily;
      canvas.add(text);
      canvas.renderAll();
    }
  });

    // Cleanup on unmount
    return () =&gt; canvas.dispose();
  }, []);

  return (
    &lt;div&gt;
      &lt;canvas id="canvas"&gt;&lt;/canvas&gt;
    &lt;/div&gt;
  );
}

ReactDOM.render(&lt;App /&gt;, document.getElementById("root"));</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script crossorigin src="https://unpkg.com/react@18/umd/react.production.min.js"&gt;&lt;/script&gt;
&lt;script crossorigin src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"&gt;&lt;/script&gt;
&lt;script src="https://cdnjs.cloudflare.com/ajax/libs/fabric.js/5.3.0/fabric.min.js"&gt;&lt;/script&gt;
&lt;script src="https://ajax.googleapis.com/ajax/libs/webfont/1.5.10/webfont.js"&gt;&lt;/script&gt;

&lt;div id="root"&gt;&lt;/div&gt;</code></pre>
</div>
</div>
</p>
<h4>2. Use native <code>new fontFace()</code> API</h4>
<p>The <a href="https://developer.mozilla.org/en-US/docs/Web/API/FontFace" rel="nofollow noreferrer">fontFace API</a> methods don't require a 3rd party font loader but require a explicit font file URL to work.</p>
<p>Related post <a href="https://stackoverflow.com/questions/2608022/how-can-i-use-custom-fonts-in-an-html5-canvas-element/2609867#2609867">&quot;How can I use custom fonts in an HTML5 Canvas element?&quot;</a></p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="true" data-babel-preset-react="true" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const { useState, useEffect } = React;


function App() {
  useEffect(async () =&gt; {
    // Initialize Fabric canvas
    const canvas = new fabric.Canvas("canvas", {
      width: 800,
      height: 200,
      backgroundColor: "#f0f0f0"
    });

    let fontFamily = 'Rasa';
    let url = 'https://fonts.gstatic.com/s/rasa/v27/xn76YHIn1mWmVKl8ZtAM9NrJfN5GJV4yd8o.woff2';

    // Add text to canvas
    const text = new fabric.Text("Hamburgefons", {
      left: 50,
      top: 80,
      fontSize: 72,
      fontFamily: fontFamily,
      fill: "#000"
    });

    let font = new FontFace(`${fontFamily}`, `url(${url})`, {style: "normal",weight: "400"});
    // wait for font to be loaded
    await font.load();
    // add font to document
    document.fonts.add(font);

    canvas.add(text);
    canvas.renderAll();

    // Cleanup on unmount
    return () =&gt; canvas.dispose();
  }, []);

  return (
    &lt;div&gt;
      &lt;canvas id="canvas"&gt;&lt;/canvas&gt;
    &lt;/div&gt;
  );
}

ReactDOM.render(&lt;App /&gt;, document.getElementById("root"));</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script crossorigin src="https://unpkg.com/react@18/umd/react.production.min.js"&gt;&lt;/script&gt;
&lt;script crossorigin src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"&gt;&lt;/script&gt;
&lt;script src="https://cdnjs.cloudflare.com/ajax/libs/fabric.js/5.3.0/fabric.min.js"&gt;&lt;/script&gt;

&lt;div id="root"&gt;&lt;/div&gt;</code></pre>
